-- Repeatable READ-ONLY Antique audit. Does not invoke mutating commands or impersonate users.
select jsonb_build_object('items',count(*),'with_photos',count(*) filter(where cardinality(media)>0),'with_value',count(*) filter(where valuation_mid>0),'bad_niche_metadata',count(*) filter(where attributes->>'niche_id' is not null and attributes->>'niche_id'<>'antiques')) as antique_inventory from public.items where public.swish_specialist_niche(specialist_id)='antiques';
select jsonb_build_object('listings',count(*),'external_ids',count(*) filter(where coalesce(l.external_listing_id,'')<>''),'tenant_mismatch',count(*) filter(where l.tenant_id<>i.tenant_id)) as antique_listings from public.listings l join public.items i on i.id=l.item_id where public.swish_specialist_niche(i.specialist_id)='antiques';
select jsonb_build_object('items_rls',(select relrowsecurity from pg_class where oid='public.items'::regclass),'listings_rls',(select relrowsecurity from pg_class where oid='public.listings'::regclass),'anon_editor_denied',not has_function_privilege('anon','public.swish_save_listing_editor(uuid,uuid,jsonb,jsonb,jsonb)','execute'),'anon_draft_denied',not has_function_privilege('anon','public.swish_create_listing_draft(uuid,uuid,text,jsonb,numeric,text)','execute')) as role_checks;
